//! `packaging/THIRD_PARTY_NOTICES.html` is generated by `scripts/notices.sh` (cargo-about), which
//! CI doesn't install. These checks catch drift without it: a crate that Cargo.lock gained or
//! changed (a dependabot update, say) and the notices don't account for fails here until the
//! script is run again.

use std::collections::BTreeSet;

const CARGO_LOCK: &str = include_str!("../../../Cargo.lock");
const NOTICES: &str = include_str!("../../../packaging/THIRD_PARTY_NOTICES.html");
const BUNDLE_SCRIPT: &str = include_str!("../../../scripts/bundle.sh");

/// `name@version` of every package in Cargo.lock that comes from a registry or git, so not our
/// own workspace crates.
fn locked_crates() -> BTreeSet<String> {
    let lock: toml_edit::DocumentMut = CARGO_LOCK.parse().expect("Cargo.lock is TOML");
    let packages = lock["package"].as_array_of_tables().expect("Cargo.lock lists packages");
    packages
        .iter()
        .filter(|p| p.contains_key("source"))
        .map(|p| {
            let field = |key: &str| p[key].as_str().unwrap_or_else(|| panic!("a package without a {key}")).to_string();
            format!("{}@{}", field("name"), field("version"))
        })
        .collect()
}

/// What follows each `marker` in the notices, up to the next `"`.
fn marked(marker: &str) -> BTreeSet<String> {
    NOTICES.split(marker).skip(1).filter_map(|rest| rest.split_once('"').map(|(value, _)| value.to_string())).collect()
}

#[test]
fn every_crate_in_cargo_lock_is_in_the_notices_or_known_not_to_ship() {
    let listed = marked("data-crate=\"");
    let not_shipped: BTreeSet<String> =
        NOTICES.lines().filter_map(|l| l.trim().strip_prefix("not-shipped: ")).map(str::to_string).collect();
    assert!(listed.len() > 300, "the notices list only {} crates", listed.len());
    let missing: Vec<_> =
        locked_crates().into_iter().filter(|c| !listed.contains(c) && !not_shipped.contains(c)).collect();
    assert!(
        missing.is_empty(),
        "Cargo.lock has crates packaging/THIRD_PARTY_NOTICES.html doesn't account for: {}. Run scripts/notices.sh \
         and commit the result.",
        missing.join(", ")
    );
}

/// The parts no crate's `license` field names: the C/C++ vendored in transcribe-cpp-sys, the
/// Lucide and Feather icons in gpui-kit-assets, SQLite; and the one MPL-2.0 crate, with where to
/// get its source (MPL-2.0 §3.2(a)).
#[test]
fn the_notices_cover_the_vendored_code_and_say_where_mpl_source_is() {
    for needle in [
        "Copyright (c) 2023-2026 The ggml authors",
        "Copyright (c) 2026 The transcribe.cpp authors",
        "Rich Geldreich",
        "Copyright 2024 Mozilla Foundation",
        "Jeffrey Quesnelle and Bowen Peng",
        "Copyright (c) 2026 Lucide Icons and Contributors",
        "Copyright (c) 2013-present Cole Bemis",
        "SQLite is in the public domain",
        "Mozilla Public License Version 2.0",
        "option-ext 0.2.0: <a href=\"https://github.com/soc/option-ext",
    ] {
        assert!(NOTICES.contains(needle), "packaging/THIRD_PARTY_NOTICES.html lacks {needle:?}");
    }
    // The text of each license in the app, Lucide's included.
    for id in ["MIT", "Apache-2.0", "ISC", "MPL-2.0", "BSD-3-Clause", "Unicode-3.0"] {
        assert!(NOTICES.contains(&format!("<h3 id=\"{id}\">")), "no {id} license text");
    }
}

/// The notices and EasyVox's own license go into the app, where the About page finds them.
#[test]
fn the_bundle_carries_the_notices_and_the_license() {
    assert!(BUNDLE_SCRIPT.contains(r#"cp packaging/THIRD_PARTY_NOTICES.html "$staging/Contents/Resources/""#));
    assert!(BUNDLE_SCRIPT.contains(r#"cp LICENSE "$staging/Contents/Resources/LICENSE.txt""#));
}
